@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700;800;900&family=DM+Sans:wght@400;500;600;700;800&display=swap');
:root{color-scheme:dark;--bg:#101114;--paper:#f5f2eb;--muted:#a6a6aa;--lime:#d8ff3e;--blue:#36a9ff;--red:#ff4c53}*{box-sizing:border-box}html,body{width:100%;height:100%;margin:0;overflow:hidden;background:#101114;color:var(--paper);font-family:'DM Sans',Arial,sans-serif;touch-action:none;user-select:none;-webkit-user-select:none}button{font:inherit;color:inherit;border:0;cursor:pointer;touch-action:manipulation}.game-shell{position:relative;width:100vw;height:100dvh;min-height:450px;overflow:hidden;background:#131519}canvas{position:absolute;inset:0;width:100%;height:100%;display:block}.topbar{position:absolute;z-index:3;top:0;left:0;right:0;height:68px;padding:0 4.3%;display:flex;align-items:center;justify-content:space-between;background:linear-gradient(180deg,rgba(8,9,12,.94),rgba(8,9,12,.54),transparent)}.brand{display:flex;align-items:center;gap:10px;background:none;text-align:left;font-weight:900;letter-spacing:1px;font-size:13px}.brand-mark{display:grid;place-items:center;width:34px;height:34px;background:var(--lime);color:#111;font:900 14px 'Barlow Condensed';transform:skew(-8deg)}.brand small{display:block;color:#a6a6aa;font-size:8px;letter-spacing:2px;margin-top:3px}.fight-info{display:flex;align-items:center;gap:18px;font:700 11px 'Barlow Condensed';letter-spacing:1.5px;color:#c3c4c6}.fight-info strong{font:800 21px 'Barlow Condensed';color:white;letter-spacing:1px}.fight-info span:last-child{color:var(--lime)}.pause-button{width:36px;height:36px;border:1px solid #ffffff3d;border-radius:50%;background:#15171cbb;font-size:16px}.hud{position:absolute;z-index:2;top:78px;left:8%;right:8%;display:grid;grid-template-columns:1fr 54px 1fr;gap:12px;align-items:start;pointer-events:none}.fighter-line{height:20px;display:flex;align-items:center;justify-content:space-between;gap:8px;font:800 14px 'Barlow Condensed';letter-spacing:1.4px}.corner-tag{font:700 8px 'DM Sans';letter-spacing:1px;color:#a6a6aa}.corner-tag.blue{color:var(--blue)}.corner-tag.red{color:#ff7378}.meter{height:17px;margin-top:6px;position:relative;background:#191c22;border:1px solid #ffffff18;overflow:hidden;transform:skew(-7deg)}.meter-fill{display:block;height:100%;width:100%;transition:width .2s;background:linear-gradient(90deg,#89d82d,var(--lime))}.enemy-hud .meter-fill{margin-left:auto;background:linear-gradient(90deg,#ff784b,#f1444d)}.meter b{position:absolute;left:7px;top:2px;color:#101114;font:900 8px 'DM Sans';letter-spacing:1px}.enemy-hud .meter b{right:7px;left:auto}.mini-meters{display:grid;grid-template-columns:1fr 1fr;gap:7px}.mini-meters .meter{height:9px;margin-top:5px}.mini-meters .meter-fill{background:#45a9eb}.enemy-hud .mini-meters .meter-fill{background:#ff705c}.mini-meters .body .meter-fill{background:#e2a947}.mini-meters .meter b{font-size:6px;top:-1px;color:#fff;text-shadow:0 1px 2px #000}.vs{padding-top:18px;text-align:center;color:#ffffff75;font:900 17px 'Barlow Condensed';font-style:italic}.combo-toast{position:absolute;z-index:4;top:29%;left:50%;transform:translate(-50%,-50%);font:900 26px 'Barlow Condensed';color:var(--lime);text-shadow:0 3px 20px #000;opacity:0;pointer-events:none}.combo-toast.show{animation:toast 1.15s ease-out}@keyframes toast{0%{opacity:0;transform:translate(-50%,10px) scale(.8)}20%{opacity:1;transform:translate(-50%,0) scale(1.1)}75%{opacity:1}100%{opacity:0;transform:translate(-50%,-24px)}}.controls{position:absolute;z-index:3;bottom:max(15px,env(safe-area-inset-bottom));left:0;right:0;height:155px;pointer-events:none;display:flex;align-items:flex-end;justify-content:space-between;padding:0 3.6%}.movement-zone,.utility-buttons,.attack-buttons{pointer-events:auto}.movement-zone{width:150px;display:flex;flex-direction:column;align-items:center;gap:4px}.stick{width:120px;height:120px;display:grid;place-items:center;touch-action:none}.stick-ring{position:relative;width:110px;height:110px;border:1px solid #ffffff40;border-radius:50%;background:radial-gradient(circle,#343840b0,#13161aa8 65%);box-shadow:0 8px 26px #0007}.stick-knob{position:absolute;left:50%;top:50%;width:49px;height:49px;border:1px solid #ffffff69;border-radius:50%;transform:translate(-50%,-50%);background:radial-gradient(circle at 35% 30%,#626873,#242830);box-shadow:0 4px 12px #0009}.stick-arrow{position:absolute;color:#ffffff65;font-size:8px}.stick-arrow.up{top:8px;left:50%;transform:translateX(-50%)}.stick-arrow.down{bottom:8px;left:50%;transform:translateX(-50%)}.stick-arrow.left{left:8px;top:50%;transform:translateY(-50%)}.stick-arrow.right{right:8px;top:50%;transform:translateY(-50%)}.move-caption{font:700 8px 'DM Sans';letter-spacing:2px;color:#ffffff8a}.utility-buttons{position:absolute;left:19%;bottom:18px;display:grid;grid-template-columns:repeat(2,53px);gap:7px}.control-btn{position:relative;display:flex;flex-direction:column;justify-content:center;align-items:center;gap:1px;border:1px solid #ffffff31;background:linear-gradient(145deg,#272b32ed,#14171ceb);box-shadow:0 4px 12px #0006;transition:transform .08s,border-color .1s,filter .1s}.control-btn:active,.control-btn.pressed{transform:scale(.92);filter:brightness(1.5);border-color:#ffffffbb}.control-btn span{font:800 18px 'Barlow Condensed';line-height:18px}.control-btn small{font:800 7px 'DM Sans';letter-spacing:.5px;color:#ffffffc2}.utility{width:53px;height:46px;border-radius:10px}.utility span{color:#d8ff3e}.utility.grab span,.utility.takedown span{color:#f3b84c}.attack-buttons{position:absolute;right:3.6%;bottom:18px;display:grid;grid-template-columns:repeat(4,58px);gap:7px}.attack{width:58px;height:56px;border-radius:12px}.attack span{width:28px;height:28px;display:grid;place-items:center;border-radius:50%;font-size:16px;background:#ffffff12}.attack.jab span,.attack.cross span{color:#5bbaff}.attack.hook span,.attack.uppercut span{color:#e5a1ff}.attack.lowkick span,.attack.highkick span{color:#ff9862}.special{width:58px;height:56px;border-radius:12px;border-color:#ddff3e9c;background:linear-gradient(145deg,#3b441a,#161a12)}.special span{font-size:19px;color:var(--lime)}.menu-screen{position:absolute;z-index:6;inset:0;display:grid;grid-template-columns:1.1fr .9fr;align-items:center;padding:8% 12%;background:linear-gradient(90deg,rgba(10,11,14,.98) 0%,rgba(10,11,14,.93) 43%,rgba(10,11,14,.28) 100%);transition:opacity .35s,visibility .35s}.menu-screen.hidden{opacity:0;visibility:hidden;pointer-events:none}.menu-copy{max-width:510px}.overline{font:800 9px 'DM Sans';letter-spacing:2px;color:#c7c7c7}.overline span{display:inline-block;width:25px;height:2px;background:var(--lime);vertical-align:middle;margin-right:8px}.menu-copy h1{margin:11px 0 2px;font:900 clamp(65px,10vw,112px)/.72 'Barlow Condensed';letter-spacing:-3px}.menu-copy h1 em{font-style:normal;color:var(--lime)}.menu-copy p{color:#c1c1c1;font-size:13px;line-height:1.7;margin:23px 0 17px}.mode-select{display:flex;gap:8px;margin-bottom:12px}.mode{padding:10px 11px;text-align:left;border:1px solid #ffffff22;background:#17191dc9;min-width:0;flex:1}.mode.active{border-color:var(--lime);background:#d8ff3e15}.mode strong{display:block;font:800 9px 'DM Sans';white-space:nowrap;letter-spacing:.3px}.mode small{display:block;font-size:8px;color:#a4a4a4;margin-top:5px;white-space:nowrap}.start-button{height:43px;padding:0 18px;background:var(--lime);color:#171a0a;font:900 10px 'DM Sans';letter-spacing:1px}.start-button span{font-size:17px;margin-left:19px}.menu-hint{margin-top:13px;color:#85878b;font:700 8px 'DM Sans';letter-spacing:.8px}.menu-fighter{height:min(75vh,590px);position:relative;display:flex;align-items:flex-end;justify-content:center}.fighter-portrait{height:100%;width:80%;position:relative;overflow:hidden;background:radial-gradient(ellipse at 55% 40%,#532f25 0,#241c1c 38%,transparent 71%)}.portrait-glow{position:absolute;width:60%;height:92%;right:5%;bottom:-10%;background:linear-gradient(135deg,#d9a178,#6a3e34 50%,#17191c);clip-path:polygon(25% 0,68% 7%,87% 24%,78% 39%,95% 47%,81% 54%,89% 64%,72% 67%,78% 100%,0 100%,11% 60%,0 44%,16% 26%);filter:drop-shadow(0 0 30px #f1924833)}.portrait-head{position:absolute;width:34%;height:28%;right:29%;top:17%;border-radius:43% 46% 35% 42%;background:linear-gradient(115deg,#c58b69,#70473b);box-shadow:inset -13px -4px #422b29}.portrait-body{position:absolute;width:76%;height:64%;right:2%;bottom:-7%;border-radius:50% 35% 0 0;background:linear-gradient(115deg,#bd8668,#553b36 56%,#171a1d);clip-path:polygon(21% 0,77% 4%,100% 30%,82% 100%,5% 100%,0 23%)}.portrait-glove{position:absolute;width:27%;height:16%;right:7%;top:40%;border-radius:40%;transform:rotate(-25deg);background:linear-gradient(135deg,#cc3540,#70181f);border:4px solid #391316;box-shadow:0 8px 20px #0008}.fighter-caption{position:absolute;bottom:2%;right:6%;display:flex;flex-direction:column;text-align:right;font:900 15px 'Barlow Condensed';letter-spacing:1px}.fighter-caption span{font:700 8px 'DM Sans';color:#aaa;margin-top:5px;letter-spacing:1.5px}.round-break,.result-screen{position:absolute;z-index:5;inset:0;display:none;place-items:center;background:#090a0dce;backdrop-filter:blur(5px)}.round-break.show,.result-screen.show{display:grid}.break-card,.result-card{text-align:center;padding:38px 55px;border:1px solid #ffffff2b;background:#14161aed;box-shadow:0 20px 70px #0009}.break-card span,.eyebrow{font:800 9px 'DM Sans';letter-spacing:2px;color:var(--lime)}.break-card strong{display:block;font:900 36px 'Barlow Condensed';margin:12px 0 25px}.break-card button,.result-card>button:not(.text-button){height:42px;padding:0 22px;background:var(--lime);color:#13150e;font:900 10px 'DM Sans';letter-spacing:1px}.result-card h1{font:900 56px 'Barlow Condensed';margin:10px 0;color:var(--lime)}.result-card p{color:#c4c4c4;font-size:13px;margin:0 0 24px}.result-card .text-button{display:block;margin:15px auto 0;background:none;color:#b9b9b9;font-size:9px;font-weight:800;letter-spacing:1px}.mobile-hint{display:none;position:absolute;bottom:5px;left:50%;transform:translateX(-50%);z-index:2;white-space:nowrap;font-size:8px;color:#ffffff70;pointer-events:none}
@media(max-width:760px){.topbar{height:53px;padding:0 4%}.brand{font-size:10px;gap:7px}.brand-mark{width:28px;height:28px}.brand small{font-size:7px}.fight-info{gap:9px}.fight-info strong{font-size:18px}.fight-info span{font-size:8px}.hud{top:61px;left:4%;right:4%;grid-template-columns:1fr 27px 1fr;gap:5px}.fighter-line{font-size:11px}.corner-tag{font-size:6px}.meter{height:14px}.mini-meters .meter{height:8px}.vs{font-size:12px}.controls{height:143px;padding:0 2%;bottom:max(8px,env(safe-area-inset-bottom))}.movement-zone{width:112px}.stick{width:103px;height:103px}.stick-ring{width:96px;height:96px}.stick-knob{width:44px;height:44px}.utility-buttons{left:calc(2% + 107px);bottom:14px;grid-template-columns:repeat(2,44px);gap:5px}.utility{width:44px;height:41px;border-radius:9px}.utility span{font-size:15px}.utility small{font-size:6px}.attack-buttons{right:2%;bottom:14px;grid-template-columns:repeat(4,48px);gap:5px}.attack,.special{width:48px;height:47px;border-radius:10px}.attack span{width:24px;height:24px;font-size:13px}.attack small,.special small{font-size:6px}.menu-screen{grid-template-columns:1fr;padding:0 8%;background:linear-gradient(90deg,rgba(10,11,14,.97),rgba(10,11,14,.72))}.menu-copy{max-width:470px}.menu-copy h1{font-size:clamp(60px,14vw,90px)}.menu-copy p{font-size:11px;margin:18px 0 13px}.mode-select{gap:5px}.mode{padding:9px 7px}.mode strong{font-size:7px}.mode small{font-size:6px}.menu-fighter{position:absolute;right:0;top:9%;height:68%;width:54%;z-index:-1;opacity:.65}.menu-hint{font-size:7px}.start-button{height:40px}.mobile-hint{display:block}}
@media(max-width:460px){.fight-info{gap:6px}.fight-info span:last-child{display:none}.hud{top:58px}.fighter-line{font-size:9px;letter-spacing:.8px}.corner-tag{letter-spacing:0;font-size:5px}.controls{bottom:max(10px,env(safe-area-inset-bottom));height:126px}.movement-zone{width:89px}.stick{width:83px;height:83px}.stick-ring{width:78px;height:78px}.stick-knob{width:37px;height:37px}.stick-arrow{font-size:6px}.utility-buttons{left:calc(1% + 84px);bottom:17px;grid-template-columns:repeat(2,38px);gap:4px}.utility{width:38px;height:37px}.utility span{font-size:13px}.utility small{font-size:5px}.attack-buttons{right:1%;bottom:17px;grid-template-columns:repeat(4,min(11.5vw,45px));gap:4px}.attack,.special{width:min(11.5vw,45px);height:43px}.attack span{width:21px;height:21px;font-size:12px}.attack small,.special small{font-size:5px;letter-spacing:0}.menu-screen{padding:0 6%}.menu-copy h1{font-size:64px}.menu-copy p{margin:13px 0;font-size:10px}.mode{padding:8px 5px}.mode strong{font-size:6px}.mode small{font-size:5px;white-space:normal}.menu-hint{max-width:220px;line-height:1.5}.menu-fighter{width:58%;opacity:.48}.mobile-hint{font-size:6px;bottom:3px}.break-card,.result-card{padding:29px 28px}.break-card strong{font-size:29px}}@media(max-height:520px){.controls{height:115px}.stick{width:88px;height:88px}.stick-ring{width:82px;height:82px}.utility-buttons{bottom:11px}.attack-buttons{bottom:11px}.utility{height:34px}.attack,.special{height:40px}.menu-copy h1{font-size:62px}.menu-copy p{margin:12px 0}.menu-fighter{height:90%}}

