(()=>{'use strict';
const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d'),W=960,H=540,$=s=>document.querySelector(s);
const ui={menu:$('#menuScreen'),start:$('#startButton'),home:$('#homeButton'),pause:$('#pauseButton'),round:$('#roundLabel'),clock:$('#clock'),status:$('#fightStatus'),toast:$('#comboToast'),brk:$('#roundBreak'),cont:$('#continueButton'),result:$('#resultScreen'),title:$('#resultTitle'),text:$('#resultText'),eyebrow:$('#resultEyebrow'),rematch:$('#rematchButton'),menu:$('#menuButton'),ph:$('#playerHealth'),eh:$('#enemyHealth'),ps:$('#playerStamina'),es:$('#enemyStamina'),pb:$('#playerBody'),eb:$('#enemyBody'),pn:$('#playerName'),en:$('#enemyName'),stick:$('#stick'),knob:$('#stickKnob')};
const moves={jab:['JAB',5,5,.36,105,'jab'],cross:['CROSS',8,8,.48,115,'cross'],hook:['HOOK',9,9,.58,105,'hook'],uppercut:['UPPERCUT',11,11,.66,90,'upper'],lowkick:['LOW KICK',8,9,.62,118,'low'],highkick:['HIGH KICK',13,15,.85,120,'high'],special:['SPECIAL',19,24,.92,128,'special'],takedown:['TAKEDOWN',13,15,.82,83,'takedown'],grab:['GRAB',3,5,.54,75,'grab']};
let p,e,mode='quick',running=false,paused=false,round=1,time=180,breakTimer=0,last=0,elapsed=0,shake=0,particles=[],texts=[],seq=[],seqTimer=0,aiTimer=1,champ=0,stickId=null,stickVec={x:0,y:0};
const names=['THE VETERAN','IRON JACKSON','EL TORO','NIGHTMARE'];
function resize(){const d=Math.min(devicePixelRatio||1,2),r=canvas.getBoundingClientRect();canvas.width=Math.round(r.width*d);canvas.height=Math.round(r.height*d);ctx.setTransform(canvas.width/W,0,0,canvas.height/H,0,0)}addEventListener('resize',resize);resize();
function fighter(x,player){return{x,y:0,homeY:player?0:0,hp:100,st:100,body:0,player,action:null,block:false,dodge:0,stun:0,flash:0,score:0,knock:0,face:player?1:-1,step:0,fallen:false,fallTime:0,damageTaken:0}}
function start(){mode=document.querySelector('.mode.active').dataset.mode;round=1;time=180;paused=false;running=true;elapsed=0;particles=[];texts=[];seq=[];champ=mode==='championship'?champ:0;p=fighter(365,true);e=fighter(595,false);e.hp=100+Math.min(champ*3,12);e.st=100;ui.pn.textContent='EL DESAFIANTE';ui.en.textContent=mode==='championship'?names[(champ+1)%names.length]:names[Math.floor(Math.random()*names.length)];ui.menu.classList.add('hidden');ui.result.classList.remove('show');ui.brk.classList.remove('show');ui.status.textContent=mode==='training'?'ENTRENAMIENTO':'COMBATE EN VIVO';ui.pause.textContent='Ⅱ';updateHud()}
function menu(){running=false;paused=false;ui.menu.classList.remove('hidden');ui.result.classList.remove('show');ui.brk.classList.remove('show');ui.status.textContent='COMBATE EN VIVO'}
ui.start.onclick=start;ui.home.onclick=menu;ui.rematch.onclick=start;ui.menu.onclick=menu;ui.cont.onclick=()=>{ui.brk.classList.remove('show');round++;time=180;p.hp=Math.min(100,p.hp+13);e.hp=Math.min(100,e.hp+10);p.st=e.st=100;updateHud()};
ui.pause.onclick=()=>{if(!running||ui.result.classList.contains('show'))return;paused=!paused;ui.pause.textContent=paused?'▶':'Ⅱ';ui.status.textContent=paused?'PAUSADO':(mode==='training'?'ENTRENAMIENTO':'COMBATE EN VIVO')};
document.querySelectorAll('.mode').forEach(b=>b.onclick=()=>{document.querySelectorAll('.mode').forEach(x=>x.classList.remove('active'));b.classList.add('active')});
function showToast(t){ui.toast.textContent=t;ui.toast.classList.remove('show');void ui.toast.offsetWidth;ui.toast.classList.add('show')}
function attack(f,key){if(!running||paused||!f||f.fallen||f.stun>0)return;if(key==='block'){f.block=true;return}if(key==='dodge'){f.dodge=.38;f.st=Math.max(0,f.st-3);f.action={key:'dodge',t:0,d:.32,hit:true};return}const data=moves[key];if(!data)return;if(f.action&&f.action.t<f.action.d*.68)return;if(f.st<data[2]*.55){showToast(f.player?'SIN RESISTENCIA':'CANSADO');return}f.st-=data[2];f.action={key,t:0,d:data[3],hit:false};f.block=false;
if(f.player){seq.push(key.toUpperCase());seqTimer=1.25;if(seq.length>4)seq.shift();const s=seq.join(' + ');if(s.includes('JAB + CROSS + HOOK')||s.includes('JAB + HOOK + UPPERCUT')||s.includes('LOW KICK + CROSS + HIGH KICK')||s.includes('JAB + CROSS + TAKEDOWN'))showToast('COMBO: '+s);else if(key==='special')showToast('MOVIMIENTO ESPECIAL');else if(key==='takedown')showToast('DERRIBO');else if(key==='grab')showToast('CLINCH');}
}
document.querySelectorAll('[data-action]').forEach(b=>{const key=b.dataset.action;b.addEventListener('pointerdown',ev=>{ev.preventDefault();b.classList.add('pressed');b.setPointerCapture(ev.pointerId);attack(p,key)});const up=ev=>{b.classList.remove('pressed');if(key==='block'&&p)p.block=false};b.addEventListener('pointerup',up);b.addEventListener('pointercancel',up);b.addEventListener('lostpointercapture',up)});
const keys={KeyW:'up',ArrowUp:'up',KeyS:'down',ArrowDown:'down',KeyA:'left',ArrowLeft:'left',KeyD:'right',ArrowRight:'right',KeyU:'jab',KeyI:'cross',KeyO:'hook',KeyP:'uppercut',KeyJ:'lowkick',KeyK:'highkick',KeyL:'block',KeyQ:'dodge',KeyE:'grab',KeyR:'takedown',KeyF:'special',Space:'special'};let held={};
addEventListener('keydown',ev=>{const a=keys[ev.code];if(a){ev.preventDefault();if(!held[ev.code]&&a!=='up'&&a!=='down'&&a!=='left'&&a!=='right')attack(p,a);held[ev.code]=true;if(a==='block'&&p)p.block=true}if(ev.code==='Escape'||ev.code==='Enter'&&ui.menu.classList.contains('hidden'))ui.pause.click()});addEventListener('keyup',ev=>{const a=keys[ev.code];held[ev.code]=false;if(a==='block'&&p)p.block=false});
