 if(!p||!e){ctx.setTransform(1,0,0,1,0,0);return}
 const aspect=w/h; const s=aspect<1.05?Math.min(1.28,Math.max(.64,w/470)):Math.min(1.24,Math.max(.6,w/960));
 const half=w/(2*s); const mid=(p.x+e.x)/2; if(half>=480)camX=480; else camX=Math.max(240,Math.min(720,mid));
 const gy=h*(aspect<1.05?.665:.70),ox=w/2-camX*s,oy=gy-390*s;
 const sx=(Math.random()-.5)*shake, sy=(Math.random()-.5)*shake;
